import React from 'react';
import { BrowserRouter, Routes, Route, useParams, useLocation, useNavigate } from 'react-router-dom';
import { Navbar } from './components/Navbar';
import { LandingPage } from './pages/LandingPage';
import { CompanionsPage } from './pages/CompanionsPage';
import { RoomPage } from './pages/RoomPage';
import { VideoCallPage } from './pages/VideoCallPage';

// Wrapper to extract room data for video call
function VideoCallPageWrapper() {
  const { roomId } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  
  const companion = location.state?.companion || { id: 'omkar_ai' };
  const userId = location.state?.userId || localStorage.getItem('userId') || `user_${Date.now()}`;

  return (
    <VideoCallPage
      companion={companion}
      roomId={roomId}
      userId={userId}
      onEndCall={() => navigate('/companions')}
    />
  );
}

// Wrapper for companions page
function CompanionsPageWrapper() {
  const navigate = useNavigate();
  
  const handleSelectCompanion = (companion) => {
    console.log('✅ Selected companion:', companion.name);
    const userId = localStorage.getItem('userId') || `user_${Date.now()}`;
    localStorage.setItem('userId', userId);
    
    // Navigate to room page with companion data
    navigate(`/room/${companion.id}`, {
      state: { companion, userId }
    });
  };

  return <CompanionsPage onSelectCompanion={handleSelectCompanion} />;
}

// Wrapper for room page
function RoomPageWrapper() {
  const { companionId } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  
  const companion = location.state?.companion || { id: companionId, name: 'AI Tutor' };
  const userId = location.state?.userId || localStorage.getItem('userId') || `user_${Date.now()}`;

  const handleJoinRoom = (roomId) => {
    console.log('✅ Joining room:', roomId);
    navigate(`/video/${roomId}`, {
      state: { companion, userId, roomId }
    });
  };

  return (
    <RoomPage
      companion={companion}
      userId={userId}
      onJoinRoom={handleJoinRoom}
      onBack={() => navigate('/companions')}
    />
  );
}

// Main layout wrapper
function LayoutWrapper({ children, showNavbar = true, showBackButton = false, onBack }) {
  const location = useLocation();
  const isVideoPage = location.pathname.includes('/video/');
  
  return (
    <div className="min-h-screen">
      {showNavbar && !isVideoPage && (
        <Navbar 
          showNav={true}
          onBack={onBack}
          showBackButton={showBackButton}
        />
      )}
      <div className={!isVideoPage ? 'pt-16' : ''}>
        {children}
      </div>
    </div>
  );
}

function App() {
  const navigate = useNavigate();

  return (
    <LayoutWrapper>
      <Routes>
        <Route path="/" element={<LandingPage onNavigate={() => navigate('/companions')} />} />
        <Route path="/companions" element={<CompanionsPageWrapper />} />
        <Route path="/room/:companionId" element={<RoomPageWrapper />} />
        <Route path="/video/:roomId" element={<VideoCallPageWrapper />} />
      </Routes>
    </LayoutWrapper>
  );
}

// Wrap App in BrowserRouter
export default function AppWithRouter() {
  return (
    <BrowserRouter>
      <App />
    </BrowserRouter>
  );
}
